/**
 *
 * FileUploadUpload is a button component that uploads the selected files when clicked.
 *
 * [Live Demo](https://www.primereact.org/fileupload/)
 *
 * @module FileUploadUpload
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { FileUploadRootInstance } from './FileUploadRoot.types';
/**
 * Defines passthrough(pt) options type in FileUploadUpload component.
 */
export type FileUploadUploadPassThroughType<E> = PassThroughType<FileUploadUploadInstance, E>;
/**
 * Defines passthrough(pt) options of FileUploadUpload component.
 */
export interface FileUploadUploadPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: FileUploadUploadPassThroughType<React.HTMLAttributes<HTMLButtonElement>>;
}
/**
 * Defines valid properties in FileUploadUpload component.
 */
export interface FileUploadUploadProps extends BaseComponentProps<FileUploadUploadInstance, unknown, FileUploadUploadPassThrough> {
}
/**
 * Defines valid state in FileUploadUpload component.
 */
export interface FileUploadUploadState {
}
/**
 * Defines the methods and properties exposed by FileUploadUpload component.
 */
export interface FileUploadUploadExposes {
    /**
     * Instance of the FileUpload component.
     */
    fileupload: FileUploadRootInstance | undefined | null;
}
/**
 * Instance of FileUploadUpload component.
 */
export type FileUploadUploadInstance = ComponentInstance<FileUploadUploadProps, FileUploadUploadState, FileUploadUploadExposes>;
